def gen(rng):
    def fmt(a):
        return f'{len(a)}\n' + ' '.join(map(str, a))

    def make(n, q, hi):
        par = rng.randint(0, 1)
        out = []
        for i in range(n):
            if i > 0 and rng.random() < q:
                par ^= 1
            r = rng.randint(1, hi)
            out.append(2 * r - 1 if par else 2 * r)
        return out

    tests = [fmt([1]), fmt([1, 2, 3, 4]), fmt([4, 8, 2, 6]), fmt([1, 2, 4]), fmt([2, 3, 5]), fmt([2, 2]),
             fmt([1, 3, 5, 7]), fmt([2, 4, 2, 3, 2, 4]), fmt([10 ** 9, 10 ** 9 - 1])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for q in (0.9, 0.5, 0.1):
            tests.append(fmt(make(n, q, 5)))
    N = 100000
    big = 5 * 10 ** 8
    tests.append(fmt(make(N, 1.0, big)))
    tests.append(fmt(make(N, 0.0, big)))
    tests.append(fmt(make(N, 0.9, big)))
    tests.append(fmt(make(N, 0.5, big)))
    return tests
